import pandas as pd
import numpy as np

# Load the datasets again
crime_data = pd.read_csv('chunks_csv/getisord/getisord_crime_second_half_2013.csv')
adjacency_data = pd.read_csv(ADJACENCY_PATH)

# Create a mapping of boroughs to their neighbors
borough_neighbors = {}
for _, row in adjacency_data.iterrows():
    borough = row['borough']
    neighbor = row['neighbor']
    if borough not in borough_neighbors:
        borough_neighbors[borough] = []
    borough_neighbors[borough].append(neighbor)

# Add each borough to its own list of neighbors
for borough in crime_data['borough']:
    if borough not in borough_neighbors:
        borough_neighbors[borough] = []

# Calculate the citywide average crime rate
citywide_average = crime_data['crime_rate_value'].mean()

# Prepare to store combined crime rates
combined_crime_rates = {}

# Calculate combined crime rates for each borough and its neighbors
for borough, neighbors in borough_neighbors.items():
    if borough in crime_data['borough'].values:
        borough_crime_rate = crime_data.loc[crime_data['borough'] == borough, 'crime_rate_value'].values[0]
        combined_crime_rate = borough_crime_rate

        for neighbor in neighbors:
            if neighbor in crime_data['borough'].values:
                neighbor_crime_rate = crime_data.loc[crime_data['borough'] == neighbor, 'crime_rate_value'].values[0]
                combined_crime_rate += neighbor_crime_rate

        combined_crime_rates[borough] = combined_crime_rate

# Calculate z-scores for combined crime rates
z_scores = {}
for borough, combined_rate in combined_crime_rates.items():
    z_score = (combined_rate - citywide_average) / (crime_data['crime_rate_value'].std() if crime_data['crime_rate_value'].std() != 0 else 1)
    z_scores[borough] = z_score

# Filter for hot and cold spots
hot_spots = {borough: z for borough, z in z_scores.items() if z > 1.96 and borough in crime_data['borough'].values}
cold_spots = {borough: z for borough, z in z_scores.items() if z < -1.96 and borough in crime_data['borough'].values}

hot_spots, cold_spots
